import{_ as p,a0 as n,w as a,s as u,ao as l,I as s,x as e,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse(`{"title":"玩轉 GitHub 的問題單（issue） | LCTT x X-CMD","titleTemplate":false,"description":"玩轉 GitHub 的問題單（issue） | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"玩轉 GitHub 的問題單（issue） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"玩轉 GitHub 的問題單（issue） | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20160718 Tips for managing your project's issue tracker","title":"玩轉 GitHub 的問題單（issue）","tag":"201611","desc":""},"relativePath":"201611/20160718 Tips for managing your project's issue tracker.md","filePath":"[post].md"}`),m={name:"201611/20160718 Tips for managing your project's issue tracker.md"};function d(f,t,g,b,T,k){const i=n("Link");return a(),u("div",null,[t[24]||(t[24]=l('<h1 id="玩轉-github-的問題單-issue" tabindex="-1">玩轉 GitHub 的問題單（issue） <a class="header-anchor" href="#玩轉-github-的問題單-issue" aria-label="Permalink to “玩轉 GitHub 的問題單（issue）”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BUSINESS_opennature_3.png?itok=30fRGfpv" alt=""></p><p><em><strong>圖片來源:</strong></em> opensource.com</p><p>對於大多數開源項目來講，問題追蹤系統（Issue-tracking system）是至關重要的。雖然有非常多的開源工具提供了這樣的功能，但是大量項目還是選擇了 GitHub 自帶的問題追蹤器（Issue Tracker）。</p><p>它結構簡單，可以讓其他人可以非常輕鬆地參與進來，但這才僅僅是開始。</p><p>如果沒有適當的處理，你的儲存庫（repository）會變得很龐大，擠滿重複的問題單、模糊不明的特性需求單、含混的 bug 報告單。項目維護者會被大量工作壓得喘不過氣來，新的貢獻者也搞不清楚項目當前的工作重點是什麼。</p><p>接下來，我們一起研究下，如何玩轉 GitHub 的問題單。</p><h3 id="問題單就是用户的故事" tabindex="-1">問題單就是用户的故事 <a class="header-anchor" href="#問題單就是用户的故事" aria-label="Permalink to “問題單就是用户的故事”">​</a></h3>',8)),s("p",null,[t[2]||(t[2]=e("我的團隊曾經和開源專家 ",-1)),o(i,{href:"http://www.jonobacon.org/"},{default:r(()=>[...t[0]||(t[0]=[e("Jono Bacon",-1)])]),_:1}),t[3]||(t[3]=e(" 做過一次對話，他是 ",-1)),o(i,{href:"http://www.artofcommunityonline.org/"},{default:r(()=>[...t[1]||(t[1]=[e("社區藝術（The Art of Community）",-1)])]),_:1}),t[4]||(t[4]=e(" 的作者、一位戰略顧問、前 GitHub 社區總監。他告訴我們，高質量的問題單是項目成功的關鍵。有些人把問題單僅僅看作是一堆你不得不去處理的問題列表，但是如果這些問題單管理完善，進行了分類並打上標籤，會令人意想不到的提升我們對代碼和社區的瞭解程度，也讓我們更清楚問題的關鍵點在哪裏。",-1))]),t[25]||(t[25]=s("p",null,"“在提交問題單時，用户不太會有耐心或者有興趣把問題的細節描述清楚。在這種情況下，你應當努力花最短的時間，儘量多的獲取有用的信息。”，Jono Bacon 説。",-1)),t[26]||(t[26]=s("p",null,"統一的問題單模板可以大大減輕項目維護者的負擔，尤其是開源項目的維護者。我們發現，讓用户講故事的方法總是可以把問題描述的非常清楚。用户講故事時需要説明“是誰，做了什麼，為什麼而做”，也就是：我是【何種用户】，為了【達到何種目的】，我要【做何種操作】。",-1)),t[27]||(t[27]=s("p",null,"實際操作起來，大概是這樣的：",-1)),t[28]||(t[28]=s("blockquote",null,[s("p",null,[e("我是一名"),s("strong",null,"顧客"),e("，我想"),s("strong",null,"購買東西"),e("，所以我想"),s("strong",null,"創建個賬户"),e("。")])],-1)),s("p",null,[t[6]||(t[6]=e("我們建議，問題單的標題始終使用這樣的用户故事形式。你可以設置",-1)),o(i,{href:"https://help.github.com/articles/creating-an-issue-template-for-your-repository/"},{default:r(()=>[...t[5]||(t[5]=[e("問題單模板",-1)])]),_:1}),t[7]||(t[7]=e("來保證一致性。",-1))]),t[29]||(t[29]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/resize/issuetemplate-new-520x293.png",alt:""})],-1)),t[30]||(t[30]=s("p",null,[s("em",null,"問題單模板讓特性需求單保持統一的形式")],-1)),t[31]||(t[31]=s("p",null,"這個做法的核心點在於，問題單要清晰的呈現給它涉及的每一個人：它要儘量簡單的指明受眾（或者説用户），操作（或者説任務），和輸出（或者説目標）。不過，不需要過分拘泥於這個模板，只要能把故事裏的是什麼事情或者是什麼原因説清楚，就達到目的了。",-1)),t[32]||(t[32]=s("h3",{id:"高質量的問題單",tabindex:"-1"},[e("高質量的問題單 "),s("a",{class:"header-anchor",href:"#高質量的問題單","aria-label":"Permalink to “高質量的問題單”"},"​")],-1)),s("p",null,[t[9]||(t[9]=e("問題單的質量是參差不齊的，這一點任何一個開源軟件的貢獻者或維護者都能證實。在",-1)),o(i,{href:"https://www.amazon.ca/Agile-Samurai-Masters-Deliver-Software/dp/1934356581"},{default:r(()=>[...t[8]||(t[8]=[e("《The Agile Samurai》",-1)])]),_:1}),t[10]||(t[10]=e("中概述過一個良好的問題單所應具備的素質。",-1))]),t[33]||(t[33]=l('<p>好的問題單儘量滿足如下條件：</p><ul><li>客户價值所在</li><li>避免使用術語或晦澀的文字，就算不是專家也能看懂</li><li>可以切分，也就是説我們可以逐步解決問題</li><li>儘量跟其他問題單沒有瓜葛，依賴其它問題會降低處理的靈活性</li><li>可以協商，也就説我們有好幾種辦法達到目標</li><li>問題足夠小，可以非常容易的評估出所需時間和資源</li><li>可衡量，我們可以對結果進行測試</li></ul><h3 id="不滿足上述條件的問題單呢-要有約束" tabindex="-1">不滿足上述條件的問題單呢? 要有約束 <a class="header-anchor" href="#不滿足上述條件的問題單呢-要有約束" aria-label="Permalink to “不滿足上述條件的問題單呢? 要有約束”">​</a></h3><p>如果一個問題單很難衡量，或者很難在短時間內完成，你也一樣有辦法搞定它。有些人把這種辦法叫做“約束”（constraints）。</p><p>例如，“這個產品要快”，這種問題單不符合故事模板，而且是沒辦法協商的。多快才是快呢？這種模糊的需求沒有達到“好問題單”的標準，但是如果你進一步定義一下，例如“每個頁面都需要在 0.5 秒內加載完”，那我們就能更輕鬆地解決它了。我們可以把“約束”看作是成功的標尺，或者要實現的里程碑。每個團隊都應該定期的對“約束”進行測試。</p><h3 id="問題單裏面有什麼" tabindex="-1">問題單裏面有什麼？ <a class="header-anchor" href="#問題單裏面有什麼" aria-label="Permalink to “問題單裏面有什麼？”">​</a></h3><p>敏捷方法中，用户故事裏通常要包含驗收指標或者標準。在 GitHub 裏，建議大家使用 markdown 格式的清單來概括解決這個問題單需要完成的任務。優先級越高的問題單應當包含更多的細節。</p><p>比如説，你打算提交一個關於新版網站主頁的問題單。那這個問題單的子任務列表可能就是這樣的：</p><p><img src="https://opensource.com/sites/default/files/resize/markdownchecklist-520x255.png" alt=""></p><p><em>使用 markdown 的清單把複雜問題拆分成多個部分</em></p><p>在必要的情況下，你還可以鏈接到其他問題單，以進一步明確任務。（GitHub 裏做這個挺方便的）</p><p>將特性定義的越細化，越容易跟蹤進度、測試，最終能更高效的發佈有價值的代碼。</p><p>以問題單的形式收到到問題所在後，還可以用 API 更深入的瞭解軟件的健康度。</p><p>“在統計問題單的類型和趨勢時，GitHub API 可以發揮巨大作用”，Bacon 告訴我們，“如果再做些數據挖掘工作，你就能發現代碼裏的問題點、社區裏的活躍成員，或者其他有用的信息。”</p><p>有些問題單管理工具提供的 API 可以提高額外信息，比如預估時間或者歷史進度。</p><h3 id="團隊協同一致" tabindex="-1">團隊協同一致 <a class="header-anchor" href="#團隊協同一致" aria-label="Permalink to “團隊協同一致”">​</a></h3><p>團隊決定使用某種問題單模板後，如何讓所有人都照做？存儲庫裏的 ReadMe.md 其實也可以是你們項目的 “How-to” 文檔。這個文檔應描述清楚這個項目是做什麼的（最好是用可以搜索的語言），以及其他貢獻者應當如何參與進來（比如提交需求單、bug 報告、建議，或者直接貢獻代碼）。</p><p><img src="https://opensource.com/sites/default/files/resize/readme-520x184.png" alt=""></p><p><em>在 ReadMe 文件裏增加清晰的説明，供新協作者參考</em></p><p>ReadMe 文件是提供“問題單指引”的完美場所。如果希望特性需求單遵循“用户講故事”的格式，那就把格式寫在 ReadMe 裏。如果使用某種跟蹤工具來管理待辦事項，那就標記在 ReadMe 裏，這樣別人也能看到。</p><p>“問題單模板、合理的標籤、提交問題單的指導文檔、確保問題單被分類並及時回應，這些對於開源項目都至關重要”，Bacon 説。</p><p>記住一點：這不是為了完成工作而做的工作。這是讓其他人更輕鬆的發現、瞭解、融入你的社區而設立的規則。</p><p>&quot;關注社區的成長，不僅要關注參與開發者的的數量增長，也要關注那些在問題單上幫助我們的人，他們讓問題單更加明確、保持更新，這是活躍溝通和高效解決問題的力量源泉&quot;，Bacon 説。</p><hr>',24)),s("p",null,[t[12]||(t[12]=e("via: ",-1)),o(i,{href:"https://opensource.com/life/16/7/how-take-your-projects-github-issues-good-great"},{default:r(()=>[...t[11]||(t[11]=[e("https://opensource.com/life/16/7/how-take-your-projects-github-issues-good-great",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=e("作者：",-1)),o(i,{href:"https://opensource.com/users/mattzenhub"},{default:r(()=>[...t[13]||(t[13]=[e("Matt Butler",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),o(i,{href:"https://github.com/echoma"},{default:r(()=>[...t[14]||(t[14]=[e("echoma",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),o(i,{href:"https://github.com/jasminepeng"},{default:r(()=>[...t[15]||(t[15]=[e("jasminepeng",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創翻譯，",-1)),o(i,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const P=p(m,[["render",d]]);export{C as __pageData,P as default};
